func prevMonthPath(year, month int) string {
	if month == 1 {
		return fmt.Sprintf("/calendar/%d/12", year-1)
	}
	return fmt.Sprintf("/calendar/%d/%d", year, month-1)
}

func nextMonthPath(year, month int) string {
	if month == 12 {
		return fmt.Sprintf("/calendar/%d/1", year+1)
	}
	return fmt.Sprintf("/calendar/%d/%d", year, month+1)
}

func monthName(month int) string {
	return time.Month(month).String()
}

func dayCellClass(day DayCell) string {
	cls := "day-cell"
	if !day.IsCurrentMonth {
		cls += " other-month"
	}
	if day.IsToday {
		cls += " today"
	}
	return cls
}

func formatEventTime(unix int64) string {
	return time.Unix(unix, 0).Format("15:04")
}

func formatEventDate(unix int64) string {
	if unix == 0 {
		return "-"
	}
	return time.Unix(unix, 0).Format("Jan 2, 2006")
}

// formatEventListDate formats an event's start date for lists. An all-day
// event is a UTC calendar date, so the server zone must not shift it.
func formatEventListDate(e *bongov1.Event) string {
	if e.AllDay {
		return icalevent.AllDayDate(e.StartTime).Format("Jan 2, 2006")
	}
	return formatEventDate(e.StartTime)
}

func truncateTitle(s string, maxLen int) string {
	if len(s) <= maxLen {
		return s
	}
	return s[:maxLen-1] + "..."
}

func eventTitle(e *bongov1.Event) string {
	if e == nil {
		return ""
	}
	return e.Title
}

func eventDescription(e *bongov1.Event) string {
	if e == nil {
		return ""
	}
	return e.Description
}

func eventLocation(e *bongov1.Event) string {
	if e == nil {
		return ""
	}
	return e.Location
}

func eventStartDate(e *bongov1.Event, date string) string {
	if e != nil && e.StartTime > 0 {
		if e.AllDay {
			return icalevent.AllDayDate(e.StartTime).Format("2006-01-02")
		}
		return time.Unix(e.StartTime, 0).Format("2006-01-02")
	}
	if date != "" {
		return date
	}
	return time.Now().Format("2006-01-02")
}

func eventStartTime(e *bongov1.Event) string {
	if e != nil && e.StartTime > 0 && !e.AllDay {
		return time.Unix(e.StartTime, 0).Format("15:04")
	}
	return "09:00"
}

func eventEndDate(e *bongov1.Event, date string) string {
	if e != nil && e.EndTime > 0 {
		t := time.Unix(e.EndTime, 0)
		if e.AllDay {
			t = icalevent.AllDayDate(e.EndTime).AddDate(0, 0, -1)
		}
		return t.Format("2006-01-02")
	}
	if date != "" {
		return date
	}
	return time.Now().Format("2006-01-02")
}

func eventEndTime(e *bongov1.Event) string {
	if e != nil && e.EndTime > 0 && !e.AllDay {
		return time.Unix(e.EndTime, 0).Format("15:04")
	}
	return "10:00"
}

func eventFormData(e *bongov1.Event, isNew bool, date string) string {
	allDay := "false"
	if e != nil && e.AllDay {
		allDay = "true"
	}
	return fmt.Sprintf("{allDay: %s}", allDay)
}

func prevWeekYear(year, week int) int {
	if week <= 1 {
		return year - 1
	}
	return year
}

func prevWeekNum(year, week int) int {
	if week <= 1 {
		return 52
	}
	return week - 1
}

func nextWeekYear(year, week int) int {
	if week >= 52 {
		return year + 1
	}
	return year
}

func nextWeekNum(year, week int) int {
	if week >= 52 {
		return 1
	}
	return week + 1
}

func prevDayPath(date time.Time) string {
	d := date.AddDate(0, 0, -1)
	return fmt.Sprintf("/calendar/day/%d/%d/%d", d.Year(), int(d.Month()), d.Day())
}

func nextDayPath(date time.Time) string {
	d := date.AddDate(0, 0, 1)
	return fmt.Sprintf("/calendar/day/%d/%d/%d", d.Year(), int(d.Month()), d.Day())
}

func dateISOYear(date time.Time) int {
	y, _ := date.ISOWeek()
	return y
}

func dateISOWeek(date time.Time) int {
	_, w := date.ISOWeek()
	return w
}

func eventBlockColor(e *bongov1.Event, calColors map[string]string) string {
	if c, ok := calColors[e.CalendarId]; ok && c != "" {
		return c
	}
	return "#4A90D9"
}

func eventBlockColourClass(e *bongov1.Event, calColors map[string]string) string {
	return CalendarColourClass(eventBlockColor(e, calColors))
}

func calendarTopClass(minutes int) string {
	if minutes < 0 {
		minutes = 0
	}
	if minutes > 1439 {
		minutes = 1439
	}
	return fmt.Sprintf("cal-top-%d", minutes)
}

func calendarHeightClass(minutes int) string {
	if minutes < 30 {
		minutes = 30
	}
	if minutes > 1440 {
		minutes = 1440
	}
	return fmt.Sprintf("cal-height-%d", minutes)
}

func CalendarColourClass(hex string) string {
	type paletteEntry struct {
		name    string
		r, g, b int
	}
	palette := []paletteEntry{
		{"blue", 59, 130, 246},
		{"green", 34, 197, 94},
		{"indigo", 99, 102, 241},
		{"orange", 245, 158, 11},
		{"red", 239, 68, 68},
		{"violet", 139, 92, 246},
		{"yellow", 234, 179, 8},
	}
	r, g, b, ok := parseHexColour(hex)
	if !ok {
		return "cal-colour-blue"
	}
	bestName := "blue"
	bestDist := -1
	for _, p := range palette {
		dr := r - p.r
		dg := g - p.g
		db := b - p.b
		dist := dr*dr + dg*dg + db*db
		if bestDist == -1 || dist < bestDist {
			bestDist = dist
			bestName = p.name
		}
	}
	return "cal-colour-" + bestName
}

func parseHexColour(hex string) (int, int, int, bool) {
	if len(hex) != 7 || hex[0] != '#' {
		return 0, 0, 0, false
	}
	var r, g, b int
	_, err := fmt.Sscanf(hex, "#%02x%02x%02x", &r, &g, &b)
	if err != nil {
		return 0, 0, 0, false
	}
	return r, g, b, true
}

// isCustomRrule reports whether a stored rule is not one of the form presets,
// so the select can offer it and round-trip it unchanged.
func isCustomRrule(r string) bool {
	switch r {
	case "", "FREQ=DAILY", "FREQ=WEEKLY", "FREQ=MONTHLY", "FREQ=YEARLY":
		return false
	}
	return true
}

